#include <stdio.h>
#include <string.h>
int main(void)
{
    int a, b, c, k;
    char str[40];

    printf("Please input a string : ");
    scanf("%s", str);

    k = strlen(str);

    /*我是快樂的分隔線一號*/

    printf("%s", str);
    for(a = 0; a < k; a++)
    {
          printf("%c", str[k-a-1]);
    }
    printf("
");

    /*我是快樂的分隔線二號*/ 

    for(b = 1; b < k; b++)
    {
          printf("%c", str[b]);

          for(c = 0; c < (k*2 - 2); c++)
          {
                printf(" ");
          }

          printf("%c
", str[b]);
    }

    /*我是快樂的分隔線三號*/

    for(b = 1; b < k; b++)
    {
          printf("%c", str[k-b]);

          for(c = 0; c < (k*2 - 2); c++)
          {
                printf(" ");
          }

          printf("%c
", str[k-b]);
    }

    /*我是快樂的分隔線四號*/

    printf("%s", str);
    for(a = 0; a < k; a++)
    {
          printf("%c", str[k-a-1]);
    }

    return 0;
}[/code]

