#include <stdio.h>
int anna(int n);
int main(void) 
{
     int x;
     printf("Enter a positive integer (q to quit).
");
     printf("Input : ");
     while (scanf("%d", &x) == 1)
     {
          if (x > 0)
          {
               printf("Output : ");
               printf("\b= %d
", anna(x));
               printf("Input : ");
          }
          else
          {
               printf("You should enter a positive integer!
");
               printf("Input : ");
          }
     }
     printf("Bye!");

     return 0;
}
int anna(int n)
{
     int ans = 0;

     if (n%2 == 1)
     {
          ans = (3*n + 1)/2 + anna(n - 1);
          printf(" %d +", (3*n + 1)/2);
     }
     if (n%2 == 0)
     {
          ans = n/2 + anna(n - 1);
          printf(" %d +", n/2);
     }
     if (n == 0)
     {
          ans = 0;
     }

     return ans;
}

